\label{thm:MT}
For every \(\varepsilon>0\), there exists \(C_\varepsilon>0\) such that
\begin{equation}\label{eq:extension-MTthm}
    \int_{B_R}|Eg|^2 w
    \leq
    C_\varepsilon R^\varepsilon
    \max_{\substack{
        \theta\in\Theta(R^{-1})\\
        g_\theta\neq0}}
    \sup_{T\parallel T_\theta}
    \left(
        \int_Tw^2
    \right)^{1/2}
    \|g\|_2^2
\end{equation}
for every \(R\geq1\), every nonnegative weight \(w\), and every
\(g\in L^2([-1,1]^2)\). In particular, 
\begin{equation}\label{main:eq2thm}
 \int_{B_R}|Eg|^2w
 \leq
 C_\varepsilon R^{1/2+\varepsilon}
 \sup_{\ell\perp\operatorname{supp} g} \left(
        \int_{N_{1}(\ell)} w^2
    \right)^{1/2}
 \|g\|_2^2,
\end{equation}
where $N_{1}(\ell)$ denotes the 1-neighborhood of the line $\ell$.

\label{thm:weightedL2}
For every \(\varepsilon>0\), there exists \(C_\varepsilon>0\) such that, for every
\(R\geq1\), every nonnegative weight \(w\), and every \(f\) satisfying
\(\operatorname{supp}\widehat f\subset N_{R^{-1}}(H)\), we have
\begin{equation}\label{eqn:mainL2}
    \int_{\mathbb R^3}|f|^2w\leq C_\varepsilon R^\varepsilon\Bigg(\sum_{\theta\in\Theta(R^{-1})}
        \sum_{T\in\mathbb T_\theta}\|f_T\|_2^2\|w\|_{L^2_{\mathrm{avg}}(T)}^2\Bigg)^{1/2}\|f\|_2.
\end{equation}
Consequently, 
\begin{equation}\label{eqn:equivL2}
    \int_{\mathbb R^3}|f|^2w
    \leq
    C_\varepsilon R^\varepsilon
    \max_{\substack{
        \theta\in\Theta(R^{-1})\\
        f_\theta\neq0}}
    \sup_{T\parallel T_\theta}
    \left(
        \frac1{|T|}
        \int_Tw^2
    \right)^{1/2}
    \|f\|_{L^2}^2.
\end{equation}

\label{thm:weightedL2refined}
    For any $\varepsilon>0$, there exists
$C_\varepsilon>0$ such that
\begin{equation}\label{eqn:goalMain}
    C(R)\leq C_\varepsilon R^\varepsilon, \quad R\geq 1.
\end{equation}

\label{lem:trivialestimate}
    Let $\mathbb{T}\subset \cup_{\theta \in \Theta_{\mathrm{square}}(R^{-1})} \mathbb{T}_\theta$, $X\subset \mathbb{R}^3$ and $N\geq 1$. Then 
\begin{align*}
    \int_X \bigg|\sum_{T\in\mathbb T}f_T\bigg|^2w
    &\lesssim_N
    \| \sum_{T\in \mathbb{T}} \chi_T^N \|_{L^\infty(X)} \sum_{T\in \mathbb{T}}\frac{\|f_T\|_2^2}{|T|}\int_X w\chi_T \\
    &\lesssim_N \| \sum_{T\in \mathbb{T}} \chi_T^N \|_{L^\infty(X)}
    \left(
        \sum_{T\in\mathbb T}
        \|f_T\|_2^2\|w\|_{L^2_{\mathrm{avg}}(T)}^2
    \right)^{1/2}\bigg(\sum_{T\in\mathbb T} \|f_T\|_2^2\bigg)^{1/2}.
\end{align*}
